type User = {id:number; username:string; role:string; must_change_password:boolean};
type Stats = {online:boolean; sessions?:number; request_rate?:number; requests?:number; bytes_in?:number; bytes_out?:number; errors_5xx?:number; version?:string; uptime?:string; error?:string; rows?:ProxyRow[];history_policy?:{raw_hours:number;fine_days:number;total_days:number}};
